def transform(grid):
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    options = {p: [] for p in cells}

    for r in range(h - 1):
        for c in range(w - 1):
            corners = [(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)]
            present = [p for p in corners if p in cells]
            if len(present) == 4:
                shape = frozenset(present)
                for p in shape:
                    options[p].append((shape, 1))
            # Any three corners form an L, including when the fourth is also 8.
            for missing_index, missing in enumerate(corners):
                shape = frozenset(p for p in corners if p != missing)
                if shape <= cells:
                    color = {0: 2, 1: 4, 2: 3, 3: 2}[missing_index]
                    for p in shape:
                        options[p].append((shape, color))

    def solve(left):
        if not left:
            return []
        p = min(left, key=lambda q: sum(shape <= left for shape, _ in options[q]))
        choices = [(shape, color) for shape, color in options[p] if shape <= left]
        choices.sort(key=lambda item: (-len(item[0]), item[1]))
        for shape, color in choices:
            rest = solve(left - shape)
            if rest is not None:
                return [(shape, color)] + rest
        return None

    tiling = solve(cells)
    result = [[0] * w for _ in range(h)]
    if tiling is not None:
        for shape, color in tiling:
            for r, c in shape:
                result[r][c] = color
    return result
